function ChapterNewUI:CheckIndex()
    if isNull(self.markerIndex) or #self.collectMarkers == 0 then
        return -1
    end

    if self.markerIndex + 1 > #self.collectMarkers then
        return 1
    end

    return 0
end

function ChapterNewUI:GetIndex(time)
    local index
    for i = 1, #self.collectMarkers do
        if self.collectMarkers[i].time > time then
            index = i - 1
            break
        end
    end
    if index == nil then
        index = #self.collectMarkers
    end
    return index
end

function ChapterNewUI:IsInBlockTime(time)
    local r = false
    for i, v in ipairs(self.blockTime) do
        if v.startTime <= time and time <= v.endTime then
            r = true
            break
        end
    end

    return r
end

function ChapterNewUI:GetSkipMarker()
    if self.currentDirector == nil then
        return -1
    end

    if self.skipPointMarkers == nil then
        return -1
    end

    local marker = nil
    for i = 1, #self.skipPointMarkers do
        if self.skipPointMarkers[i].time > self.currentDirector.director.time then
            marker = self.skipPointMarkers[i]
            break
        end
    end

    if isNull(marker) then
        return 0
    else
        return marker
    end
end

-- 获取一个分段timeline里面所有的mark配置信息
function ChapterNewUI:GetSkipConfigs(director)
    -- 保存 UIContentMarker 和 UIAutoContentMarker
    self.collectMarkers = {}
    self.skipPointMarkers = {}
    self.blockMarkers = {}
    self.silenceDealMarkers = {}
    self.blockTime = {}

    self.currentDirector = {}
    self.currentDirector.director = director
    self.currentDirector.controller = director.gameObject:EnsureComponent(typeof(TimelineController))

    local track = self:GetTrackByType(director, typeof(CustomMarkerTrack))
    if not isNull(track) then
        local list = self:GetMarkers(track)
        for i = 1, list.Count do
            local index = i - 1
            local markerType = list[index]:GetType()
            if markerType == typeof(UIContentMarker) or markerType == typeof(UIAutoContentMarker) then
                table.insert(self.collectMarkers, list[index])
            elseif markerType == typeof(SkipPointMarker) then
                table.insert(self.skipPointMarkers, list[index])
            elseif markerType == typeof(CS.Game.Native.QTE.QTEFullScreenTouchMarker) then
                table.insert(self.blockMarkers, list[index])
            elseif markerType == typeof(CS.Markers.BlockSkipStartMarker) then
                table.insert(self.blockMarkers, list[index])
                local tb = {}
                tb.startTime = list[index].time
                tb.endTime = isNull(list[index].EndMarker) and self.currentDirector.director.duration or list[index].EndMarker.time
                table.insert(self.blockTime, tb)
            end
        end

    end

    track = self:GetTrackByType(director, typeof(TimelineNotificationTrcak))
    if not isNull(track) then
        local list = self:GetMarkers(track)
        for i = 1, list.Count do
            local index = i - 1
            local markerType = list[index]:GetType()
            if markerType == typeof(CS.Game.Native.QTE.QTEFullScreenTouchMarker) then
                table.insert(self.blockMarkers, list[index])
            elseif markerType == typeof(CS.Game.Native.QTE.QTEDragMarker) then
                table.insert(self.blockMarkers, list[index])
            elseif markerType == typeof(CS.Game.Native.QTE.QTEShowMainSceneMarker) then
                table.insert(self.silenceDealMarkers, list[index])
            elseif markerType == typeof(CS.Game.Native.QTE.QTERectTouchMarker) then
                table.insert(self.blockMarkers, list[index])
            elseif markerType == typeof(CS.Game.Native.QTE.QTELongTouchMarker) then
                table.insert(self.blockMarkers, list[index])
            elseif markerType == typeof(CS.Game.Native.QTE.QTESoundPlayMarker) then
                table.insert(self.silenceDealMarkers, list[index])
            elseif markerType == typeof(CS.Markers.GameObjectActiveMarker) then
                table.insert(self.silenceDealMarkers, list[index])
            end
        end
    end

    if #self.collectMarkers > 1 then
        table.sort(self.collectMarkers, function(a, b)
            return a.time < b.time
        end)
    end

    if #self.skipPointMarkers > 1 then
        table.sort(self.skipPointMarkers, function(a, b)
            return a.time < b.time
        end)
    end

    if #self.blockMarkers > 1 then
        table.sort(self.blockMarkers, function(a, b)
            return a.time < b.time
        end)
    end

    if #self.silenceDealMarkers > 1 then
        table.sort(self.silenceDealMarkers, function(a, b)
            return a.time < b.time
        end)
    end
end

function ChapterNewUI:GetBlockMarker(currentTime, destTime)
    local block
    for i = 1, #self.blockMarkers do
        local time = self.blockMarkers[i].time
        if currentTime <= time and destTime >= time then
            block = self.blockMarkers[i]
            break
        end
    end

    return block
end

function ChapterNewUI:GetBlockUI()
    if self.currentDirector == nil or self.currentDirector.director == nil then
        return 
    end
    local blockName = "heimu"
    local parent = self.currentDirector.director.transform
    local tmp = parent:Find(blockName)
    if not isNull(tmp) then
        return tmp
    end
    tmp = parent:Find("UI")
    if isNull(tmp) then
        tmp = parent:Find("Canvas")
    end

    if isNull(tmp) then
        return nil
    end
    
    return tmp:Find(blockName)
    
end

function ChapterNewUI:SilenceProcess(currentTime, destTime)
    for i = 1, #self.silenceDealMarkers do
        local time = self.silenceDealMarkers[i].time
        local markerType = self.silenceDealMarkers[i]:GetType()
        if currentTime <= time and destTime >= time then
            if markerType == typeof(CS.Game.Native.QTE.QTEShowMainSceneMarker) then
                --table.insert(self.silenceDealMarkers, list[index])
                self:OpenMain()
            elseif markerType == typeof(CS.Game.Native.QTE.QTESoundPlayMarker) then
                --table.insert(self.silenceDealMarkers, list[index])
                self:OnSound(self.silenceDealMarkers[i])
            elseif markerType == typeof(CS.Markers.GameObjectActiveMarker) then
                --table.insert(self.silenceDealMarkers, list[index])
                self:ActiveObj(self.silenceDealMarkers[i])
            end
        end
    end

end

function ChapterNewUI:ActiveObj(notification)
    local obj = notification.ControlObj:Resolve(self.currentDirector.director);
    if isNull(obj) then
        return
    end
    KTool.SetActive(obj, notification.State);
end

function ChapterNewUI:OnSound(notification)
    local soundId = notification.soundId
    if notification.isStop then
        CriWareUtils.StopById(soundId)
        return
    end
    if notification.isBGM
    or notification.alwaysPlay then
        CriWareUtils.PlayMusicById(soundId)
    end
end

function ChapterNewUI:OpenMain()
    local sceneManagement = SceneManagement:GetInstance()
    local sceneData = sceneManagement:GetScenePathInfo(self.OP1Env.sceneId)
    sceneManagement:SetActive(sceneData.id, true)
    CfUtils.ChangeMainCamDefalultBlend(0)
    KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, false)

end

