function ChapterNewUI:InitLayout()
    KTool.SetActive(self.Dialog, false)
    KTool.SetActive(self.CreateName, false)

    if self._chapterType == ChapterConstants.ChapterType.PreDownload  then
        KTool.SetActive(self.TgAuto.transform.parent, false)
        KTool.SetActive(self.BtnUIControl, false)
        KTool.SetActive(self.BtnPlotReview, false)
    end

    self.Control.transform:SetAsLastSibling()
    KTool.SetActive(self.BtnSpeed.gameObject, false)
    self.DistortComp = self.IconHead.gameObject:GetComponent(typeof(CS.RandomDistortion))
end

function ChapterNewUI:OpenDialog()
    if not isNull(self.Tween) then
        self.Tween:Kill()
    end

    self.Tween = self.Dialog.gameObject:GetComponent(typeof(CanvasGroup)):DOFade(1, 0.25)
    if isNull(self.TxtContent:GetTextComp()) then
        return
    end
    self.TxtContent:SetText("")

    if not self.visible then
        return
    end

    --KTool.SetActive(self.DialogBtn, true)

    KTool.SetActive(self.Dialog, true)

end

function ChapterNewUI:FindStartBg(startRowId, endRowId)
    ---@type NewChapter2DVo
    local vo = self.DialogSetting:Get(startRowId)
    if vo == nil then
        return
    end

    if not string.isEmpty(vo.sceneId) and vo.type ~= NewChapterConstants.NewType.StartAnimation then
        self.startBg = {}
        self.startBg.sceneId = vo.sceneId
        self.startBg.sceneType = vo.sceneType
        return
    end
    if (vo.nextId ~= 0 or vo.nextId > endRowId) then
        self:FindStartBg(vo.nextId, endRowId)
    else
        printInfo("no start bg")
    end
end

