function ChapterNewUI:SetAutoPlay(state)
    if state then
        if self._sequenceNext ~= nil then
            if not self.IsTyping and not self.HasOption then
                printInfo("Invoke")
                self.DialogBtn.onClick:Invoke()
            end
        end
    end
    self.AutoPlay = state
    printInfo("SetAutoPlay ")
    printInfo(state)
end

function ChapterNewUI:SetVisible(state)
    if state then
        self._preAuto = self.AutoPlay
        self.AutoPlay = false
    else
        self.AutoPlay = self._preAuto

    end
    self:FinishType()
    self.visible = not state
    KTool.SetActive(self.Dialog, not state)
    --KTool.SetActive(self.Option, not state)
    printInfo("SetVisible ")
    printInfo(state)
end

function ChapterNewUI:SetUIJumpCtrl(state)
    if not state then
        KTool.SetActive(self.DialogBtn, false)
    end
end

function ChapterNewUI:SmallSkip()

    if self._isQTEChapter then
        return false
    end

    if self._sequenceNext ~= nil then
        return false
    end

    if self.currentDirector == nil or self.currentDirector.director == nil then
        return false
    end
    
    local currentTime = self.currentDirector.director.time

    if self:IsInBlockTime(currentTime) then
        return false
    end

    local curIndex = self:GetIndex(currentTime)

    self.markerIndex = curIndex

    local checked = self:CheckIndex()
    if checked < 0 then
        return false
    end

    if self._dialogCo ~= nil then
        cs_coroutine.stop(self._dialogCo)
        self._dialogCo = nil
    end

    if self.disableCo ~= nil then
        cs_coroutine.stop(self.disableCo)
        self.disableCo = nil
    end

    if self._isPause then
        self:Resume(true)
    end

    --if checked == 1 then
    --    print("jumpEnd")
    --    self.currentDirector.controller:SetTime(self.currentDirector.director.duration - 0.02)
    --    return true
    --end

    --local index = self:GetIndex() + 1
    ----KTool.SetActive(self.DialogBtn, false)
    --local time = self.collectMarkers[index].time
    --print("jump ", time)
    --self.currentDirector.controller:SetTime(time - 0.01)
    --return true


    local index = curIndex + 1
    local destTime = checked == 1 and self.currentDirector.director.duration or self.collectMarkers[index].time

    local blockMarker = self:GetBlockMarker(currentTime, destTime)
    if not isNull(blockMarker) then
        destTime = blockMarker.time
        KTool.SetActive(self.DialogBtn, false)
    end
    local ui = self:GetBlockUI()
    if not isNull(ui) and checked ~= 1 then
        local img = ui.gameObject:GetComponent(typeof(ImageComp))
        local c = img.color
        c.a = 0
        img.color = c
    end
    self:SilenceProcess(currentTime, destTime)
    self:StopSE(self._cachedVo)
    self.currentDirector.controller:SetTime(destTime - 0.02)
    return true
end

function ChapterNewUI:Refresh(id)
    
    assert(type(id) == "number")
    if self._dialogCo ~= nil then
        cs_coroutine.stop(self._dialogCo)
        self._dialogCo = nil
    end
    
    self.DialogBtn.onClick:RemoveAllListeners()

    --printInfo("ChapterNewUI:Refresh %s %s" , tostring(id) , debug.traceback())
    if id == 0 or not self.initialized then
        --self.controller:Close()
        --Events.Broadcast(ChapterConstants.ChapterEvents.OnChapterEndDialog)

        --KTool.SetActive(self.Dialog, false)

        --KTool.SetActive(self.DialogBtn, false)

        self.Tween = self.Dialog.gameObject:GetComponent(typeof(CanvasGroup)):DOFade(0, 0.25)

        if self._isPause then
            self:Resume()
        end

        if self._teleportEffect and not isNull(self.DistortComp) then
            self.DistortComp.enabled = false
        end

        self._teleportEffect = false

        --阻挡了op7引导点击了
        KTool.SetActive(self.DialogBtn, false)
        KTool.SetActive(self.OverlayBtn, false)

        if self._sequenceNext ~= nil then
            self._sequenceNext = nil
            if self._slowClose ~= nil then
                cs_coroutine.stop(self._slowClose)
                self._slowClose = nil
            end
            self._slowClose = cs_coroutine.start(function()

                KTool.SetActive(self.BlockUI.transform.parent, true)

                self.BlockUI:DOColor(Color.New(0, 0, 0, 1), self.Duration)

                coroutine.yield(Yielders.GetWaitForSeconds(self.Duration))

                KTool.SetActive(self.BlockUI.transform.parent, false)

                local current = self.CsEnv:GetCurrentDirector()
                self.timelineBlock = current.gameObject:GetComponentInChildren(typeof(ImageComp))
                KTool.SetActive(self.timelineBlock, true)

                if KTool.IsActiveInHierarchy(self.cg.gameObject) then
                    KTool.SetActive(self.cg, false)
                end

                self._slowClose = nil

                if isNull(self.bgMovie) then
                    return
                end

                if not isNull(self.bgMovie.player) then
                    self.bgMovie:Stop()
                end

                --不能直接关 要等几帧彻底结束
                coroutine.yield()
                coroutine.yield()
                coroutine.yield()

                if KTool.IsActiveInHierarchy(self.bgMovie.gameObject) then
                    KTool.SetActive(self.bgMovie.gameObject, false)
                end
            end)
        end

        self._needHead = false

        self._afterOption = false

        self._cachedPath = nil

        self._cachedBgMovie = nil

        self._modifyModel = nil

        self._modifyBs = nil

        self._modifyRigSpeaker = nil

        return
    end

    if self.record == nil then
        self.record = {}
    end
    
    self._dialogCo = cs_coroutine.start(function()

        --携程没stop干净 临时保护 后期优化流程可去掉
        if self == nil or self.DialogSetting == nil then
            return
        end
        --coroutine.yield()
        ---@type NewChapter2DVo
        local currentDialog = self.DialogSetting:Get(id)

        if currentDialog == nil then
            printError("%d not found %d", self.CsEnv.ChapterId, id)
            return
        end

        if self._sequenceNext == nil then
            if self._afterOption == true and currentDialog.characterName ~= "我" then
                printInfo("??")
                self.Tween = self.Dialog.gameObject:GetComponent(typeof(CanvasGroup)):DOFade(0, 0.25)
                self:Refresh(0)
                return
            end
        else
            self._afterOption = nil
        end

        printInfo("refresh %d", id)

        print("dialog:", table.dump(currentDialog))

        self._cachedVo = currentDialog

        self.IsTyping = true

        self:LoadBg(currentDialog)

        self:ProcessSE(currentDialog)

        self:SetContentName(currentDialog.characterName)

        self:SetIconHead(currentDialog.avatar)

        local content = self:FillPlaceHold(currentDialog.desc, currentDialog.characterName)

        --if currentDialog.type ~= NewChapterConstants.NewType.ChapterOption  then
        if not NewChapterUtils.HasOption(currentDialog) then
            if not (self.recordCell ~= nil and self.recordCell.owner == currentDialog.characterName and self.recordCell.content == content) then
                self.recordCell = {}
                self.recordCell.owner = currentDialog.characterName
                printInfo("insert %s", table.dump(self.recordCell))
                table.insert(self.record, self.recordCell)
            end
            
        end

        if not string.isEmpty(content) then
            self.recordCell.content = content
        end

        --self.TxtContent.text = "invaild parameters " .. id
        KTool.SetActive(self.grid.gameObject, false)

        -- 点击屏幕可以立刻finish打字机的效果
        local dialogClick = function()
            if self.BlockClick then
                return
            end

            --if self:SmallSkip() then
            --    return
            --end

            if self._isQTEChapter then
                return
            end

            if not self.AutoPlay then
                self.DialogBtn.onClick:RemoveAllListeners()

                self:FinishType()

            end
            --printInfo("DialogBtn")
        end

        self:SetButtonClick(self.DialogBtn, dialogClick)

        KTool.SetActive(self.DialogBtn, true);

        self.HasOption = not string.isEmpty(currentDialog.option)


        --self:ProcessEvent(currentDialog.event, currentDialog.parameter)

        local txtContent = self.TxtContent
        txtContent.AppearDuration = 0.2
        txtContent.PendingTime = self:GetPendingTime()
        txtContent.TextWillFill = content
        txtContent.SplitlineEffect = false

        self._wait = true

        self._waitCo = cs_coroutine.start(function()

            coroutine.yield(txtContent:StartType())

            self._wait = false
        end)

        if self._blockWait ~= nil and self._blockWait > 0 then

            local cached = self.BlockClick == true
            self.BlockClick = true
            self._blockCo = cs_coroutine.start(function()

                printInfo("start " .. tostring(self.BlockClick))
                printInfo("wait " .. tostring(self._blockWait))

                coroutine.yield(Yielders.GetWaitForSeconds(self._blockWait))

                self.BlockClick = cached

                printInfo("end " .. tostring(self.BlockClick))
            end)


        end

        while self._wait do
            coroutine.yield()
        end

        if self._waitCo ~= nil then
            cs_coroutine.stop(self._waitCo)
        end
        self._waitCo = nil

        if isNull(txtContent:GetTextComp()) then
            return
        end

        txtContent:StopType()
        txtContent:ShowAll()

        printInfo("finish type")
        self.IsTyping = false
        if self.HasOption then

            --print_to_file(currentDialog.option)
            local split = currentDialog.option
            local len = #split
            local subsplit = currentDialog.jumpId

            --KTool.SetActive(self.grid.gameObject, true)
            if not isNull(self.recordCell) then
                self.recordCell.option = {}
            end
            for i = 1, self.grid.childCount do

                local btn = self.grid:GetChild(i - 1).gameObject:GetComponent(typeof(ButtonComp))
                KTool.SetActive(btn.gameObject, i <= len)
                if i <= len then
                    --printInfo(split[i + len - self.grid.childCount])
                    printInfo(split[i])
                    ---@type NewChapterOptionVo
                    --local vo = self.OptionSetting:Get(split[i])
                    local optionContent = self:FillPlaceHold(split[i])

                    if not isNull(self.recordCell) then

                        table.insert(self.recordCell.option, optionContent)
                    end
                    btn.transform:GetChild(0):Find("Text"):GetComponent(typeof(TextComp)).text = optionContent
                    self:SetButtonClick(btn, function()
                        --printInfo(subsplit[2])
                        if self.BlockClick then
                            return
                        end
                        --self.DialogBtn.onClick:RemoveAllListeners()

                        if not isNull(self.recordCell) then
                            self.recordCell.selectIndex = i
                        end
                        --cs_coroutine.stop(self._dialogCo)
                        printInfo(subsplit[i])

                        self._afterOption = true

                        self.HasOption = false
                        
                        self:Refresh(tonumber(subsplit[i]))
                    end)
                end

            end
            KTool.SetActive(self.grid.gameObject, true)
            self.DialogBtn.onClick:RemoveAllListeners()
            KTool.SetActive(self.DialogBtn, false)
        else
            --self.recordCell.content = content

            --self.HasOption = false
            printInfo("?！")
            KTool.SetActive(self.grid.gameObject, false)
            self:SetButtonClick(self.DialogBtn, function()
                if self.BlockClick then
                    return
                end

                if not self.AutoPlay then
                    if self._sequenceNext ~= nil then

                        if isSet(self._sequenceNext, currentDialog.id) then
                            self:Refresh(self._sequenceNext[currentDialog.id])
                        else
                            self:Refresh(currentDialog.nextId)
                        end
                        return
                    end

                    --if self._overrideNext then
                    --    self._overrideNext = false
                    --    self:Refresh(0)
                    --    printInfo("override")
                    --
                    --else
                    --    
                    --    self:Refresh(currentDialog.nextId)
                    --end

                    if self:SmallSkip() then
                        return
                    end


                end


            end)
        end

        --self._finishCall()
        --self._finishCall = nil
        --
        --self._dialogCo = nil

        self:ResetArgs()

        self._finishCall = nil


        if self._afterOption then
            self._afterOption = nil
            self._dialogCo = nil
            
            self.disableCo = cs_coroutine.start(function()
                KTool.SetActive(self.OverlayBtn, true)
                coroutine.yield(Yielders.GetWaitForSeconds(0.5))
                self:Refresh(0)
                self.disableCo = nil
            end)
        else
            if self.AutoPlay or self._convertAuto then
                if self.HasOption then
                    self._convertAuto = nil
                    return
                end

                local wait = nil
                if self._convertAuto then
                    self._convertAuto = nil
                    printInfo("AutoSkip Invoke")

                    wait = 0.5
                else
                    wait = 1
                    printInfo("AutoPlay Invoke")

                    while not self.voiceFinish do
                        coroutine.yield()
                    end
                end

                if not isNull(self.disableCo) then
                    coroutine.yield(self.disableCo)
                else
                    coroutine.yield(Yielders.GetWaitForSeconds(wait))

                    self._dialogCo = nil

                    if self._sequenceNext ~= nil then
                        if isSet(self._sequenceNext, currentDialog.id) then
                            self:Refresh(self._sequenceNext[currentDialog.id])
                        else
                            self:Refresh(currentDialog.nextId)
                        end
                    else
                        self:Refresh(0)
                    end
                end

            else
                self._dialogCo = nil
            end
        end

        

    end)

end

