    --    CriWareUtils.PlayMusic(vo.music[1], vo.music[2])
    --end
    if not self._isQTEChapter then
        self:ProcessMusic(vo)

        if not string.isEmpty(vo.sound) then
            --AudioManager:EnsurePlaySFX(vo.sound, NewChapterConstants.AudioMarker)
            CriWareUtils.PlaySeById(vo.sound)

            if self.soundRecord.SERecord == nil then
                self.soundRecord.SERecord = {}
            end
            table.insert(self.soundRecord.SERecord, vo.sound)
        end

        if not string.isEmpty(vo.loopSE) then
            --AudioManager:EnsurePlaySFX(vo.loopSE, NewChapterConstants.AudioMarker)
            CriWareUtils.PlaySeById(vo.loopSE)

            -- 把所有播放过的音效都记录下来，退出剧情的时候全都关掉
            if self.soundRecord.loopSERecord == nil then
                self.soundRecord.loopSERecord = {}
            end
            table.insert(self.soundRecord.loopSERecord, vo.loopSE)
        end
    end

    self.voiceFinish = false
    if not string.isEmpty(vo.voice) then
        --AudioManager:EnsurePlaySFX(vo.voice, NewChapterConstants.AudioMarker)
        local tmp = self:GetSpeaker(vo)
        printInfo("voice %s %s", vo.voice, tostring(tmp))

        local slice = CriWareUtils.PlaySeById(vo.voice, tmp)
        if not isNull(slice) then
            if not isNull(tmp) then
                local arr = tmp.gameObject:GetComponentsInChildren(typeof(CS.UnityEngine.SkinnedMeshRenderer), true)
                self._modifyModel = {}
                for i = 1, arr.Length do
                    local model = arr[i - 1]
                    local str = model.name
                    if str == "face" or str == "mouth" then
                        local t = {}
                        t.skinned = model
                        t.willModify = {}
                        for j = 1, model.sharedMesh.blendShapeCount do
                            if NewChapterUtils.NeedModify(model.sharedMesh:GetBlendShapeName(j - 1)) then
                                table.insert(t.willModify, j - 1)
                            end
                        end
                        table.insert(self._modifyModel, t)
                    end
                    self._modifyBs = true
                end
                self._modifyRigSpeaker = tmp.gameObject:GetInstanceID()
                -- printInfo("will modify %s %s %s", tostring(self._modifyBs), self._modifyRigSpeaker, tostring(table.dump(self._modifyModel)))

            else
                self._modifyBs = false
                self._modifyModel = nil
                self._modifyRigSpeaker = nil
            end

            slice.onFinish = function()
                self.voiceFinish = true
                printInfo("voice finish %s", vo.voice)
            end
        else
            self._modifyBs = false
            self._modifyModel = nil
            self._modifyRigSpeaker = nil
            self.voiceFinish = true
        end

    else
        self.voiceFinish = true
    end
end

function ChapterNewUI:StopSE(vo)
    if not self._isQTEChapter then
        --self:ProcessMusic(vo)

        if not string.isEmpty(vo.sound) then
            --AudioManager:EnsurePlaySFX(vo.sound, NewChapterConstants.AudioMarker)
            CriWareUtils.StopById(vo.sound)
        end

        if not string.isEmpty(vo.loopSE) then
            --AudioManager:EnsurePlaySFX(vo.loopSE, NewChapterConstants.AudioMarker)
            CriWareUtils.StopById(vo.loopSE)
        end

        if not string.isEmpty(vo.voice) then
            CriWareUtils.StopById(vo.voice)
        end
    end
end

--- 预处理收集嘴巴的骨骼和初始位置信息
function ChapterNewUI:PreprocessSpeakerMouse()
    self._speakerMouseRigs = {}
    self._speakerMouseRigsDefaults = {}

    local current = self.CsEnv.transform.parent

    local lips = current.gameObject:GetComponentsInChildren(typeof(CS.CriWare.CriLipsDeformerForAtomSource), true)
    for i = 1, lips.Length do
        local tmp = lips[i - 1].gameObject
        local rigs = ChapterUtils.CollectMouseRig(tmp.transform)
        if table.count(rigs) > 0 then
            self._speakerMouseRigs[tmp:GetInstanceID()] = rigs

            local rigDefaults = {}
            for i, rig in ipairs(rigs) do
                local defaultValue = {}
                defaultValue.pos = rig.localPosition
                defaultValue.rot = rig.localRotation
                defaultValue.scl = rig.localScale

                table.insert(rigDefaults, defaultValue)
            end
            self._speakerMouseRigsDefaults[tmp:GetInstanceID()] = rigDefaults
        end
    end

    -- print("[嘴型] 预处理", table.dump(self._speakerMouseRigs, nil, 3), table.dump(self._speakerMouseRigsDefaults, nil ,3))
end

---@param vo ChapterDialogVo
function ChapterNewUI:GetSpeaker(vo)
    if vo.speaker == 0 then
        return nil
    end

    --local current = self.CsEnv:GetCurrentDirector()
    --if isNull(current) then
    --    return nil
    --end
    local current = self.CsEnv.transform.parent

    if self._speakers == nil then
        self._speakers = {}
    end

    if isSet(self._speakers, vo.speaker) then
        if KTool.IsActiveInHierarchy(self._speakers[vo.speaker]) then
            return self._speakers[vo.speaker]
        end
    end

    local lips = current.gameObject:GetComponentsInChildren(typeof(CS.CriWare.CriLipsDeformerForAtomSource))
    for i = 1, lips.Length do
        local tmp = lips[i - 1].gameObject.name
        printInfo("%s %d", tmp, tostring(vo.speaker))
        if string.contains(tmp, tostring(vo.speaker)) or string.contains(tostring(vo.speaker), tmp) then
            self._speakers[vo.speaker] = lips[i - 1].gameObject
            printInfo("found %s %s ", tostring(vo.speaker), tostring(lips[i - 1].gameObject))
            break
        end
    end

    if self._speakers[vo.speaker] == nil and self.CsEnv.IsQTEChapter then
        local roleRoot = CS.UnityEngine.GameObject.Find("Role")
        if not isNull(roleRoot) then
            local tlLip = roleRoot:GetComponentsInChildren(typeof(CS.CriWare.CriLipsDeformerForAtomSource))
            for i = 1, tlLip.Length do
                local tmp = tostring(vo.speaker)
                --vo.speaker 108008
                --tltip 主界面上的人 108
                if string.contains(tmp, tlLip[i - 1].gameObject.name) then
                    self._speakers[vo.speaker] = tlLip[i - 1].gameObject
                    break
                end
            end
        end

    end

    return self._speakers[vo.speaker]
end

function ChapterNewUI:GetCharacter(characterId)
    local dirTrans = self.currentDirector.director.transform
    local charParentName = characterId .. "_loc"
    local tmpTrans = dirTrans:Find("allposition")
    if isNull(tmpTrans) then
        tmpTrans = dirTrans:Find(charParentName)
    end
    if isNull(tmpTrans) then
        return nil
    end

    local r = tmpTrans:Find(characterId)
    if not isNull(r) then
        r = r.gameObject
    end
    return r
end

