function ChapterNewUI:ProcessEvent(event, param)
    --assert(type(event) == "string")

    --todo [string "Game.Chapter.ChapterNewUI"]:473: attempt to concatenate a nil value
    --print("event" .. table.dump(event))
    for i = 1, #event do
        if event[i] == "Resume" then
            --self.Processor.DirectorControl:ResumeCurrent()
            --self._processor:ResumeDirector()
            self.CsEnv:ResumeDirector()
        elseif event[i] == "SplitlineEffect" then
            self._splitlineEffect = true
        elseif event[i] == "Wait" then
            self._blockWait = checkNumber(param[i])
        end
    end

end

