function ChapterNewUI:ModifyMouseRig()
    if isNull(self._modifyRigSpeaker) then return end

    local rigs = self._speakerMouseRigs[self._modifyRigSpeaker]
    local rigDefaults = self._speakerMouseRigsDefaults[self._modifyRigSpeaker]

    if isNull(rigs) or isNull(rigDefaults) then
        return
    end

    -- for i, rig in ipairs(rigs) do
    --     local defaults = rigDefaults[i]
    --     rig.localPosition = Vector3.zero
    --     rig.localRotation = Quaternion.identity
    --     rig.localScale = Vector3.one
    -- end

    for i, rig in ipairs(rigs) do
        local defaults = rigDefaults[i]
        rig.localPosition = defaults.pos
        rig.localRotation = defaults.rot
        rig.localScale = defaults.scl
    end
end

function ChapterNewUI:OnDestroy()
    --self.TxtContent:StopType()
    if self.disableCo ~= nil then
        cs_coroutine.stop(self.disableCo)
        self.disableCo = nil
    end
    if self._waitCo ~= nil then
        cs_coroutine.stop(self._waitCo)
        self._waitCo = nil
    end
    if self._dialogCo ~= nil then
        cs_coroutine.stop(self._dialogCo)
        self._dialogCo = nil
    end

    if self._slowClose ~= nil then
        cs_coroutine.stop(self._slowClose)
        self._slowClose = nil
    end

    if self._cachedBgCo ~= nil then
        cs_coroutine.stop(self._cachedBgCo)
        self._cachedBgCo = nil
    end

    if self.seqCo ~= nil then
        cs_coroutine.stop(self.seqCo)
        self.seqCo = nil
    end

    if self._lateUpdater ~= nil then
        MonoHelper.RemoveLateUpdateListener(self._lateUpdater)
    end

    if not isNull(self.CsEnv) then
        local lips = self.CsEnv.transform.parent.gameObject:GetComponentsInChildren(typeof(CriLipsDeformerForAtomSource), true)
        if not isNull(lips) then
            for i = 1, lips.Length do
                local tmp = lips[i - 1]
                if not isNull(tmp.atomAnalyzer) then
                    tmp.atomAnalyzer:Dispose()
                end
            end
        end
    end

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

function ChapterNewUI:GetTrackByType(director, trackType)
    local list = support.new_list(typeof(CS.UnityEngine.Timeline.TrackAsset))
    list:AddRange(director.playableAsset:GetOutputTracks())

    local track = nil
    --printInfo(trackName)
    for i = 0, list.Count - 1 do
        if list[i]:GetType() == trackType then
            --printInfo(mute)
            track = list[i]
            break
        end
    end

    return track
end

function ChapterNewUI:GetTrackByName(director, name)
    local list = support.new_list(typeof(CS.UnityEngine.Timeline.TrackAsset))
    list:AddRange(director.playableAsset:GetOutputTracks())

    local track = nil
    --printInfo(trackName)
    for i = 0, list.Count - 1 do
        if list[i].name == name then
            --printInfo(mute)
            track = list[i]
            break
        end
    end

    return track
end

